fn getdomain(x: Vec<i8>) -> Vec<i8> {
    // Since the input vector is guaranteed to be non-empty,
    // we can safely take the first element as an initial min and max.
    let mut iter = x.into_iter();
    let first = iter.next().unwrap();
    let mut min = first;
    let mut max = first;

    // Traverse the rest of the elements, updating min and max as needed.
    for v in iter {
        if v < min {
            min = v;
        }
        if v > max {
            max = v;
        }
    }

    // Return a 2-element vector [min, max].
    vec![min, max]
}

